package it.comune.trieste.ouf.udp;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.sql.Types;
import java.time.OffsetDateTime;
import java.util.*;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class SpatialMaterializer {
  private final JdbcClient db;private final ObjectMapper json;private final GovernedCrsTransform transformations;
  public SpatialMaterializer(JdbcClient db,ObjectMapper json,GovernedCrsTransform transformations){this.db=db;this.json=json;this.transformations=transformations;}

  @Transactional public Result materialize(String handoffId,UUID sourceObjectId,Map<String,Object> handoff,UdpPorts.SpatialProfile profile){
    var transformed=prepare(handoffId,handoff,profile);if(!"OK".equals(transformed.status()))return new Result(false,0,1);
    return materializePrepared(handoffId,sourceObjectId,handoff,profile,transformed);
  }
  /** Validation precedes identity creation, so a rejected layer does not create empty Urban Objects. */
  public GovernedCrsTransform.Result prepare(String handoffId,Map<String,Object> handoff,UdpPorts.SpatialProfile profile){
    var identity=HandoffIntakeService.object(handoff,"sourceIdentity");
    try{var from=time(identity.get("validFrom"));var to=time(identity.get("validTo"));if(from!=null&&to!=null&&!from.isBefore(to))throw new IllegalArgumentException();}
    catch(RuntimeException invalid){issue(handoffId,null,null,"SPATIAL_POLICY_INVALID",List.of(),Map.of("reason","INVALID_VALIDITY_INTERVAL","policyRef",profile.policyRef()));return new GovernedCrsTransform.Result("SPATIAL_POLICY_INVALID",null,null,Map.of());}
    Object raw=HandoffIntakeService.object(handoff,"canonicalPayload").get(profile.geometry().sourceField());
    Map<?,?> envelope=raw instanceof Map<?,?> map?map:Map.of();
    var transformed=raw instanceof Map<?,?>?transformations.transform(envelope,profile.geometry()):new GovernedCrsTransform.Result("SPATIAL_INVALID_GEOMETRY",null,null,Map.of());
    if(!"OK".equals(transformed.status())){Map<String,Object> details=new LinkedHashMap<>(transformed.evidence());details.put("policyRef",profile.policyRef());details.put("sourceCrs",envelope.get("crs"));details.put("expectedSourceCrs",profile.geometry().expectedSourceCrs());details.put("canonicalSrid",profile.geometry().canonicalSrid());details.put("crsPolicy",profile.geometry().crsPolicy());issue(handoffId,null,null,transformed.status(),List.of(),details);}
    return transformed;
  }
  Result materializePrepared(String handoffId,UUID sourceObjectId,Map<String,Object> handoff,UdpPorts.SpatialProfile profile,GovernedCrsTransform.Result transformed){
    if(!"OK".equals(transformed.status()))throw new IllegalArgumentException("UDP_SPATIAL_REVIEW_REQUIRED");
    Map<?,?> envelope=(Map<?,?>)HandoffIntakeService.object(handoff,"canonicalPayload").get(profile.geometry().sourceField());
    UUID geometryRevision=storeGeometry(handoffId,sourceObjectId,handoff,profile,envelope,transformed);int matched=0,review=0;for(var rule:profile.relationships()){List<Candidate> candidates=find(sourceObjectId,geometryRevision,rule);if(candidates.isEmpty()){if("QUARANTINE_RELATION".equals(rule.onNoMatch())){issue(handoffId,sourceObjectId,rule.relationIri(),"SPATIAL_NO_MATCH",List.of(),evidence(profile,rule));review++;}continue;}if(ambiguous(candidates,rule)){issue(handoffId,sourceObjectId,rule.relationIri(),"SPATIAL_MULTIPLE_MATCHES",candidates.stream().map(Candidate::id).toList(),evidence(profile,rule));review++;continue;}UUID target=candidates.getFirst().id();if(target.equals(sourceObjectId)&&!rule.selfLoopAllowed()){issue(handoffId,sourceObjectId,rule.relationIri(),"SELF_LOOP_NOT_ALLOWED",List.of(target),evidence(profile,rule));review++;continue;}writeEdge(handoffId,sourceObjectId,target,rule,geometryRevision,profile.policyRef(),candidates.getFirst().metric());matched++;}return new Result(true,matched,review);
  }
  private UUID storeGeometry(String handoff,UUID object,Map<String,Object> payload,UdpPorts.SpatialProfile profile,Map<?,?> original,GovernedCrsTransform.Result transformed){return storeGeometry(handoff,object,payload,profile,original,transformed,true);}
  private UUID storeGeometry(String handoff,UUID object,Map<String,Object> payload,UdpPorts.SpatialProfile profile,Map<?,?> original,GovernedCrsTransform.Result transformed,boolean advance){
    String hash=hash(Map.of("canonicalEwkb",transformed.canonicalEwkb(),"source",original,"transformation",transformed.evidence(),"contractRefs",payload.get("contractRefs"),"accessLabel",profile.geometry().accessLabel(),"sourceIdentity",Map.of("sourceId",HandoffIntakeService.object(payload,"sourceIdentity").get("sourceId"),"typeCode",HandoffIntakeService.object(payload,"sourceIdentity").get("typeCode"),"sourceObjectId",HandoffIntakeService.object(payload,"sourceIdentity").get("sourceObjectId")),"geometryRole",profile.geometry().geometryRole(),"validity",validity(payload)));
    List<UUID> old=db.sql("select geometry_revision_id from ouf_udp.urban_geometry where urban_object_id=:u and geometry_hash=:h and normalization_version=:n").param("u",object).param("h",hash).param("n",profile.geometry().normalizationVersion()).query(UUID.class).list();
    UUID id;if(old.isEmpty()){
      id=UUID.randomUUID();Map<String,Object> evidence=new LinkedHashMap<>(transformed.evidence());evidence.put("handoffRef","handoff://"+handoff);evidence.put("lineageRef",payload.get("lineageId"));evidence.put("normalizationVersion",profile.geometry().normalizationVersion());evidence.put("contractRefs",payload.get("contractRefs"));evidence.put("policyRef",profile.policyRef());evidence.put("geometryRole",profile.geometry().geometryRole());evidence.put("sourceField",profile.geometry().sourceField());evidence.put("validity",validity(payload));
      db.sql("insert into ouf_udp.urban_geometry(geometry_revision_id,urban_object_id,handoff_id,geometry,canonical_geometry,source_geometry_json,geometry_hash,source_crs,canonical_srid,normalization_version,access_label,evidence_json,geometry_role,valid_from,valid_to) values(:i,:u,:h,ST_GeomFromEWKB(decode(:g,'hex')),ST_GeomFromEWKB(decode(:canonical,'hex')),cast(:original as jsonb),:x,:s,:srid,:n,:a,cast(:e as jsonb),:role,:from,:to)")
        .param("i",id).param("u",object).param("h",handoff).param("g",transformed.servingEwkb()).param("canonical",transformed.canonicalEwkb()).param("original",write(original)).param("x",hash).param("s",profile.geometry().expectedSourceCrs()).param("srid",profile.geometry().canonicalSrid()).param("n",profile.geometry().normalizationVersion()).param("a",profile.geometry().accessLabel()).param("e",write(evidence)).param("role",profile.geometry().geometryRole()).param("from",time(HandoffIntakeService.object(payload,"sourceIdentity").get("validFrom")),Types.TIMESTAMP_WITH_TIMEZONE).param("to",time(HandoffIntakeService.object(payload,"sourceIdentity").get("validTo")),Types.TIMESTAMP_WITH_TIMEZONE).update();
    }else id=old.getFirst();
    if(advance){db.sql("insert into ouf_udp.urban_geometry_role_current(urban_object_id,geometry_role,geometry_revision_id) values(:u,:role,:g) on conflict(urban_object_id,geometry_role) do update set geometry_revision_id=excluded.geometry_revision_id").param("u",object).param("role",profile.geometry().geometryRole()).param("g",id).update();}
    if(advance&&"PRIMARY".equals(profile.geometry().geometryRole()))db.sql("insert into ouf_udp.urban_geometry_current(urban_object_id,geometry_revision_id) values(:u,:g) on conflict(urban_object_id) do update set geometry_revision_id=excluded.geometry_revision_id").param("u",object).param("g",id).update();return id;
  }
  /** Published processing must arbitrate geometry before changing either current view. */
  String currentAction(String handoff,UUID object,Map<String,Object> payload,UdpPorts.SpatialProfile spatial,UdpPorts.MaterializationProfile materialization,GovernedCrsTransform.Result transformed){
    var identity=HandoffIntakeService.object(payload,"sourceIdentity");var now=OffsetDateTime.now();var from=time(identity.get("validFrom"));var to=time(identity.get("validTo"));
    if((from!=null&&from.isAfter(now))||(to!=null&&!to.isAfter(now))){storeGeometry(handoff,object,payload,spatial,(Map<?,?>)HandoffIntakeService.object(payload,"canonicalPayload").get(spatial.geometry().sourceField()),transformed,false);return from!=null&&from.isAfter(now)?"FUTURE":"HISTORICAL_ONLY";}
    var current=db.sql("select g.geometry_revision_id,g.access_label,g.valid_from,g.valid_to,h.source_id,h.payload_json::text previous_payload,ST_Equals(g.geometry,ST_GeomFromEWKB(decode(:g,'hex'))) equivalent from ouf_udp.urban_geometry_role_current c join ouf_udp.urban_geometry g on g.geometry_revision_id=c.geometry_revision_id join ouf_udp.handoff_intake h on h.handoff_id=g.handoff_id where c.urban_object_id=:u and c.geometry_role=:role").param("role",spatial.geometry().geometryRole()).param("g",transformed.servingEwkb()).param("u",object).query().listOfRows();
    if(current.isEmpty())return "ADVANCE";
    var old=current.getFirst();if((old.get("valid_from") instanceof OffsetDateTime start&&start.isAfter(now))||(old.get("valid_to") instanceof OffsetDateTime end&&!end.isAfter(now)))return "ADVANCE";String source=HandoffIntakeService.text(HandoffIntakeService.object(payload,"sourceIdentity"),"sourceId");
    boolean sameSource=source.equals(old.get("source_id"));
    if(sameSource){
      var previousIdentity=HandoffIntakeService.object(read(String.valueOf(old.get("previous_payload"))),"sourceIdentity");
      var previousTime=time(previousIdentity.get("observedAt"));var incomingTime=time(identity.get("observedAt"));
      if(previousTime!=null&&incomingTime!=null&&incomingTime.isBefore(previousTime)){storeGeometry(handoff,object,payload,spatial,(Map<?,?>)HandoffIntakeService.object(payload,"canonicalPayload").get(spatial.geometry().sourceField()),transformed,false);return "HISTORICAL_ONLY";}
      if(previousTime!=null&&incomingTime!=null&&incomingTime.isAfter(previousTime))return "ADVANCE";
      if(Boolean.TRUE.equals(old.get("equivalent"))&&spatial.geometry().accessLabel().equals(old.get("access_label")))return "RETAIN";
      // Equal or absent source timestamps cannot establish which distinct shape is newer.
    }
    var rule=materialization.properties().stream().filter(p->p.sourceField().equals(spatial.geometry().sourceField())).findFirst().orElseThrow(()->new IllegalArgumentException("UDP_GEOMETRY_AUTHORITY_REQUIRED"));
    int incoming=rule.authorityOrder().indexOf(source),previous=rule.authorityOrder().indexOf(String.valueOf(old.get("source_id")));
    incoming=incoming<0?10000:incoming;previous=previous<0?10000:previous;
    if(incoming<previous)return "ADVANCE";
    Map<?,?> original=(Map<?,?>)HandoffIntakeService.object(payload,"canonicalPayload").get(spatial.geometry().sourceField());
    UUID candidate=storeGeometry(handoff,object,payload,spatial,original,transformed,false);
    var human=db.sql("select chosen_geometry_revision from ouf_udp.human_geometry_decision where urban_object_id=:u and policy_ref=:p and ((previous_geometry_revision=:old and candidate_geometry_revision=:candidate) or (previous_geometry_revision=:candidate and candidate_geometry_revision=:old)) order by decided_at desc limit 1")
      .param("u",object).param("p",materialization.policyRef()).param("old",old.get("geometry_revision_id")).param("candidate",candidate).query(UUID.class).optional();
    if(human.isPresent())return human.get().equals(candidate)?"ADVANCE":"RETAIN";
    if(incoming>previous)return "RETAIN";
    if(Boolean.TRUE.equals(old.get("equivalent"))&&spatial.geometry().accessLabel().equals(old.get("access_label")))return "RETAIN";
    issue(handoff,object,null,"SPATIAL_AUTHORITY_CONFLICT",List.of(object),Map.of("policyRef",materialization.policyRef(),"currentGeometryRevision",old.get("geometry_revision_id"),"candidateGeometryRevision",candidate,"geometryProperty",rule.propertyIri(),"geometryRole",spatial.geometry().geometryRole(),"comparison","TOPOLOGICAL_EQUALS_IN_SERVING_CRS","action","REVIEW_REQUIRED"));
    return "REVIEW_REQUIRED";
  }
  private static OffsetDateTime time(Object value){return value==null?null:OffsetDateTime.parse(String.valueOf(value));}
  private static Map<String,Object> validity(Map<String,Object> payload){var source=HandoffIntakeService.object(payload,"sourceIdentity");var result=new TreeMap<String,Object>();for(String key:List.of("validFrom","validTo"))if(source.get(key)!=null)result.put(key,source.get(key));return result;}
  private Map<String,Object> read(String value){try{return json.readValue(value,new com.fasterxml.jackson.core.type.TypeReference<>(){});}catch(Exception e){throw new IllegalStateException(e);}}
  private List<Candidate> find(UUID source,UUID geometry,UdpPorts.SpatialRelationshipRule r){String predicate=r.predicate();if("NEAREST".equals(predicate)&&r.maxDistanceMeters()==null)throw new IllegalArgumentException("UDP_SPATIAL_MAX_DISTANCE_REQUIRED");String condition=switch(predicate){case "INTERSECTS"->"ST_Intersects(s.geometry,t.geometry)";case "WITHIN"->"ST_Within(s.geometry,t.geometry)";case "CONTAINS"->"ST_Contains(s.geometry,t.geometry)";case "NEAREST"->"ST_DWithin(s.geometry::geography,t.geometry::geography,:distance)";case "OVERLAP_RATIO"->"ST_Area(ST_Intersection(s.geometry,t.geometry)::geography)/nullif(ST_Area(s.geometry::geography),0)>=:overlap";default->throw new IllegalArgumentException("UDP_SPATIAL_PREDICATE_UNSUPPORTED");};String sql="select o.urban_object_id,ST_Distance(s.geometry::geography,t.geometry::geography) metric from ouf_udp.urban_geometry s join ouf_udp.urban_geometry_active tc on true join ouf_udp.urban_geometry t on t.geometry_revision_id=tc.geometry_revision_id join ouf_udp.urban_object o on o.urban_object_id=tc.urban_object_id where s.geometry_revision_id=:g and o.tenant_id=(select tenant_id from ouf_udp.urban_object where urban_object_id=s.urban_object_id) and o.canonical_type=:t and o.status='ACTIVE' and "+condition+" order by metric,o.urban_object_id";var spec=db.sql(sql).param("g",geometry).param("t",r.targetCanonicalType());if(sql.contains(":distance"))spec=spec.param("distance",r.maxDistanceMeters());if(sql.contains(":overlap")){if(r.minOverlapRatio()==null)throw new IllegalArgumentException("UDP_SPATIAL_MIN_OVERLAP_REQUIRED");spec=spec.param("overlap",r.minOverlapRatio());}return spec.query((rs,n)->new Candidate(rs.getObject("urban_object_id",UUID.class),rs.getDouble("metric"))).list();}
  private static boolean ambiguous(List<Candidate> c,UdpPorts.SpatialRelationshipRule r){if(c.size()==1)return false;if(!"NEAREST".equals(r.predicate())||r.rankingMarginMeters()==null)return true;return c.get(1).metric()-c.getFirst().metric()<r.rankingMarginMeters();}
  private void writeEdge(String handoff,UUID source,UUID target,UdpPorts.SpatialRelationshipRule rule,UUID geometry,String policy,double metric){UUID contribution=UUID.randomUUID();String sourceHash=hash(Map.of("geometryRevision",geometry,"target",target));Map<String,Object> provenance=Map.of("handoffRef","handoff://"+handoff,"geometryRevisionRef","geometry://"+geometry,"predicate",rule.predicate(),"policyRef",policy,"metricMeters",metric);db.sql("insert into ouf_udp.relationship_contribution(contribution_id,handoff_id,source_object_id,relation_iri,source_value,source_value_hash,strategy_ref,policy_ref,access_label,provenance_json) values(:i,:h,:s,:r,cast(:v as jsonb),:x,:t,:p,:a,cast(:e as jsonb)) on conflict(handoff_id,relation_iri,source_value_hash) do nothing").param("i",contribution).param("h",handoff).param("s",source).param("r",rule.relationIri()).param("v",write(Map.of("geometryRevision",geometry))).param("x",sourceHash).param("t",rule.predicate()).param("p",policy).param("a",rule.accessLabel()).param("e",write(provenance)).update();contribution=db.sql("select contribution_id from ouf_udp.relationship_contribution where handoff_id=:h and relation_iri=:r and source_value_hash=:x").param("h",handoff).param("r",rule.relationIri()).param("x",sourceHash).query(UUID.class).single();UUID relationship=UUID.nameUUIDFromBytes((source+"|"+rule.relationIri()+"|"+target).getBytes(StandardCharsets.UTF_8));db.sql("insert into ouf_udp.urban_relationship(relationship_id,source_object_id,relation_iri,target_object_id) values(:i,:s,:r,:t) on conflict(source_object_id,relation_iri,target_object_id) do nothing").param("i",relationship).param("s",source).param("r",rule.relationIri()).param("t",target).update();relationship=db.sql("select relationship_id from ouf_udp.urban_relationship where source_object_id=:s and relation_iri=:r and target_object_id=:t").param("s",source).param("r",rule.relationIri()).param("t",target).query(UUID.class).single();String evidenceHash=hash(Map.of("geometry",geometry,"target",target,"predicate",rule.predicate(),"metric",metric));List<UUID> old=db.sql("select relationship_revision_id from ouf_udp.relationship_revision where relationship_id=:r and evidence_hash=:h").param("r",relationship).param("h",evidenceHash).query(UUID.class).list();if(old.isEmpty()){UUID revision=UUID.randomUUID();long no=db.sql("select coalesce(max(revision_no),0)+1 from ouf_udp.relationship_revision where relationship_id=:r").param("r",relationship).query(Long.class).single();db.sql("insert into ouf_udp.relationship_revision(relationship_revision_id,relationship_id,revision_no,contribution_id,evidence_hash,resolution_evidence,access_label) values(:i,:r,:n,:c,:h,cast(:e as jsonb),:a)").param("i",revision).param("r",relationship).param("n",no).param("c",contribution).param("h",evidenceHash).param("e",write(provenance)).param("a",rule.accessLabel()).update();db.sql("update ouf_udp.urban_relationship set current_revision_id=:v where relationship_id=:r").param("v",revision).param("r",relationship).update();}}
  private void issue(String handoff,UUID source,String relation,String reason,List<UUID> candidates,Map<String,Object> evidence){db.sql("insert into ouf_udp.spatial_resolution_issue(issue_id,handoff_id,source_object_id,relation_iri,reason_code,candidate_refs,evidence_json) values(gen_random_uuid(),:h,:s,:r,:c,cast(:a as jsonb),cast(:e as jsonb)) on conflict do nothing").param("h",handoff).param("s",source,Types.OTHER).param("r",relation,Types.VARCHAR).param("c",reason).param("a",write(candidates.stream().map(x->"urban-object://"+x).toList())).param("e",write(evidence)).update();}
  private static Map<String,Object> evidence(UdpPorts.SpatialProfile p,UdpPorts.SpatialRelationshipRule r){Map<String,Object> e=new LinkedHashMap<>();e.put("policyRef",p.policyRef());e.put("predicate",r.predicate());e.put("sourceCrs",p.geometry().expectedSourceCrs());e.put("canonicalSrid",p.geometry().canonicalSrid());e.put("normalizationVersion",p.geometry().normalizationVersion());e.put("maxDistanceMeters",r.maxDistanceMeters());e.put("minOverlapRatio",r.minOverlapRatio());e.put("rankingMarginMeters",r.rankingMarginMeters());return e;}
  private String hash(Object value){try{return "sha256:"+HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.copy().configure(com.fasterxml.jackson.databind.SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS,true).writeValueAsBytes(value)));}catch(Exception e){throw new IllegalStateException(e);}}
  private String write(Object value){try{return json.writeValueAsString(value);}catch(JsonProcessingException e){throw new IllegalArgumentException("UDP_JSON_INVALID",e);}}
  private record Candidate(UUID id,double metric){}
  public record Result(boolean geometryStored,int relationshipsMaterialized,int issuesOpened){}
}
